const RR = 74, CM = 10, MX = 200, MY = 105;
function P(lo, la) {
  const a = Math.min(90, Math.abs(la)), i = Math.min(17, Math.floor(a / 5)), t = (a - i * 5) / 5;
  const X = ROB[i][0] + (ROB[i + 1][0] - ROB[i][0]) * t, Y = ROB[i][1] + (ROB[i + 1][1] - ROB[i][1]) * t;
  const dl = Math.max(-180, Math.min(180, lo - CM));
  return [MX + 0.8487 * RR * X * dl * Math.PI / 180, MY - Math.sign(la) * 1.3523 * RR * Y];
}
const pkt = (txt) => txt.trim().split(/\s+/).map((t) => {
  const hart = t.endsWith("!"); if (hart) t = t.slice(0, -1);
  const roh = t.startsWith("@"); if (roh) t = t.slice(1);
  const [a, b] = t.split(",").map(Number);
  const [x, y] = roh ? [a, b] : P(a, b);
  return { x, y, hart };
}).filter((q, i, a) => !i || Math.hypot(q.x - a[i - 1].x, q.y - a[i - 1].y) > 0.04);
function weg(pts, zu = true, k = 1) {
  if (typeof pts === "string") pts = pkt(pts);
  const n = pts.length, at = (i) => zu ? pts[(i + n) % n] : pts[Math.max(0, Math.min(n - 1, i))];
  let d = `M${r(pts[0].x)} ${r(pts[0].y)}`;
  for (let i = 0; i < (zu ? n : n - 1); i++) {
    const p0 = at(i - 1), p1 = at(i), p2 = at(i + 1), p3 = at(i + 2);
    const c1 = p1.hart ? p1 : { x: p1.x + (p2.x - p0.x) / 6 * k, y: p1.y + (p2.y - p0.y) / 6 * k };
    const c2 = p2.hart ? p2 : { x: p2.x - (p3.x - p1.x) / 6 * k, y: p2.y - (p3.y - p1.y) / 6 * k };
    d += `C${r(c1.x)} ${r(c1.y)} ${r(c2.x)} ${r(c2.y)} ${r(p2.x)} ${r(p2.y)}`;
  }
  return d + (zu ? "Z" : "");
}
/* Linie in Länge/Breite mit Zwischenpunkten (für Gradnetz und Ozeangrenzen) */
const linie = (pts, n = 6) => { const o = []; for (let i = 0; i < pts.length - 1; i++) for (let j = 0; j < n; j++) { const t = j / n; o.push(`${pts[i][0] + (pts[i + 1][0] - pts[i][0]) * t},${pts[i][1] + (pts[i + 1][1] - pts[i][1]) * t}`); } o.push(pts[pts.length - 1].join(",")); return o.join(" "); };
