const halo = (x, y, t, gr, farbe, hf, extra = "", hb = 0.8) => `<text x="${r(x)}" y="${r(y)}" font-size="${gr}" text-anchor="middle" fill="${farbe}" stroke="${hf}" stroke-width="${hb}" stroke-linejoin="round" paint-order="stroke" ${SERIF} ${extra}>${t}</text>`;

