/* =====================================================================
   KULISSE — Papier, Ozean (Robinson-Oval), Gradnetz, Küstensaum, Antarktis
   ===================================================================== */
const OVAL = (() => { const a = []; for (let la = 90; la >= -90; la -= 5) a.push(`${CM + 180},${la}`); for (let la = -90; la <= 90; la += 5) a.push(`${CM - 180},${la}`); return weg(pkt(a.join(" ")).map((q, i) => i % 37 === 0 || i % 37 === 36 ? Object.assign(q, { hart: true }) : q)); })();
S.def(`<path id="${S.id("oval")}" d="${OVAL}"/>`);
S.def(`<clipPath id="${S.id("ovalclip")}">${USE("oval")}</clipPath>`);
/* jeder Kontinent einmal als Pfad in <defs>; Küstensaum und Kontinent-Teile verweisen darauf */
for (const [k, ringe] of Object.entries(LAND)) S.def(`<path id="${S.id("k_" + k)}" d="${ringe.map((t) => weg(t)).join("")}"/>`);
S.def(`<g id="${S.id("land")}">${Object.keys(LAND).map((k) => USE("k_" + k)).join("")}</g>`);
{
  let g = `<rect x="-2" y="-2" width="${BR + 4}" height="${HO + 4}" fill="${PAPIER}"/>`;
  g += USE("oval", `fill="#7a5a2a" opacity=".22" transform="translate(.6 .9)" filter="url(#${S.id("weich")})"`) + USE("oval", `fill="${OZEAN}"`);
  /* Gradnetz: alle 30° */
  let n = "";
  for (let lo = CM - 180 + 30; lo < CM + 180; lo += 30) n += weg(linie([[lo, 90], [lo, -90]], 18), false);
  for (const la of [-60, -30, 30, 60]) n += weg(linie([[CM - 180, la], [CM + 180, la]], 4), false);
  g += `<path d="${n}" fill="none" stroke="#fff" stroke-width=".3" opacity=".45"/>`;
  g += `<path d="${weg(linie([[CM - 180, 0], [CM + 180, 0]], 4), false)}" fill="none" stroke="#c0503a" stroke-width=".35" stroke-dasharray="2 1.2" opacity=".55"/>`;
  for (const la of [23.44, -23.44]) g += `<path d="${weg(linie([[CM - 180, la], [CM + 180, la]], 4), false)}" fill="none" stroke="#fff" stroke-width=".3" stroke-dasharray="1 1.4" opacity=".6"/>`;
  /* Küstensaum: helle Wasserlinien um alles Land */
  g += `<g clip-path="url(#${S.id("ovalclip")})" fill="none" stroke-linejoin="round">${USE("land", `stroke="#d7eef4" stroke-width="3.4" opacity=".55"`)}${USE("land", `stroke="#eef9fb" stroke-width="1.5" opacity=".75"`)}</g>`;
  S.def(`<pattern id="${S.id("wellen")}" width="11" height="6" patternUnits="userSpaceOnUse"><path d="M.5 3.5 q1.2 -1.2 2.4 0 t2.4 0" fill="none" stroke="#fff" stroke-width=".25" opacity=".5"/></pattern>`);
  g += USE("oval", `fill="url(#${S.id("wellen")})" opacity=".6"`);
  /* Antarktis */
  g += `<path d="${weg(ANTARKTIS)}" fill="${S.lg("eis", [[0, "#ffffff"], [1, "#e3eef3"]])}" stroke="#9fbccb" stroke-width=".35" clip-path="url(#${S.id("ovalclip")})"/>`;
  g += USE("oval", `fill="none" stroke="#7d6340" stroke-width=".6"`);
  S.hinten(g);
}
/* Beschriftungen auf dem Wasser, Äquator, Wendekreise */
{
  let g = "";
  const wl = (lo, la, t, gr = 3, extra = "") => { const [x, y] = P(lo, la); return halo(x, y, t, gr, "#3f7896", "#d6ecf2", `font-style="italic" letter-spacing=".5" ${extra}`, 0.6); };
  g += wl(-150, 77.5, "N o r d p o l a r m e e r", 3) + wl(10, -63, "S ü d p o l a r m e e r", 3.2);
  { const [x, y] = P(-25, 1.2); g += text(x, y, "Äquator", 2.6, "#a8453a", `font-style="italic" letter-spacing=".4"`); }
  { const [x, y] = P(10, -82.5); g += text(x, y, "A N T A R K T I S", 3.4, "#7f98a6", `letter-spacing=".8"`); }
  S.hinten(g);
}
/* Bilderbuch: ein Segelschiff im Südatlantik, ein Wal im Pazifik */
{
  let [x, y] = P(-36, -50);
  let g = `<g transform="translate(${r(x)} ${r(y)})"><path d="M-3.4 -.6 L3.6 -.6 L2.6 .9 L-2.6 .9 Z" fill="#7a5232"/><path d="M-.2 -.6 V-6" stroke="#5a3a22" stroke-width=".3"/><path d="M0 -5.8 Q2.6 -3.6 0 -1.1 Z" fill="#fbf6ea"/><path d="M-.4 -5.4 Q-2.8 -3.4 -.4 -1.2 Z" fill="#efe6d2"/><path d="M-.2 -6 l1.2 .4 l-1.2 .4 Z" fill="#c0392b"/><path d="M-4.2 1.2 q1 -.6 2 0 t2 0 t2 0 t2 0" fill="none" stroke="#fff" stroke-width=".3" opacity=".8"/></g>`;
  [x, y] = P(-150, -38);
  g += `<g transform="translate(${r(x)} ${r(y)})"><path d="M-4.2 0 Q-3.6 -2.4 -.4 -2.3 Q2.6 -2.2 3.4 -.4 Q4.4 -.9 5 -2 Q5.2 -.6 4.6 .2 Q2.8 .8 -1.6 .7 Q-3.6 .6 -4.2 0 Z" fill="#5d7f99"/><path d="M-3.8 .1 Q-1 .9 3.4 -.3" fill="none" stroke="#dbe8f0" stroke-width=".35"/><circle cx="-2.8" cy="-.9" r=".25" fill="#1d2b36"/><path d="M-1.6 -2.3 q-.4 -1.2 -1.2 -1.6 M-1.6 -2.3 q.3 -1.3 1.1 -1.6" fill="none" stroke="#e8f4fa" stroke-width=".3"/></g>`;
  S.hinten(g);
}
/* Windrose und Kartusche in den Ecken außerhalb des Ovals */
{
  const cx = 22, cy = 186;
  let g = `<circle cx="${cx}" cy="${cy}" r="12" fill="#fbf4e2" opacity=".7"/><circle cx="${cx}" cy="${cy}" r="12" fill="none" stroke="#8a6d43" stroke-width=".35"/><circle cx="${cx}" cy="${cy}" r="10.6" fill="none" stroke="#8a6d43" stroke-width=".2"/>`;
  for (let i = 0; i < 8; i++) {
    const a = i * Math.PI / 4, lang = i % 2 ? 6.4 : 10, b = i % 2 ? 1.1 : 1.7;
    const sx = Math.sin(a), sy = -Math.cos(a), qx = Math.cos(a), qy = Math.sin(a);
    const tip = [cx + sx * lang, cy + sy * lang], l = [cx + qx * b, cy + qy * b], rr = [cx - qx * b, cy - qy * b];
    g += `<path d="M${r(cx)} ${r(cy)} L${r(l[0])} ${r(l[1])} L${r(tip[0])} ${r(tip[1])} Z" fill="${i % 2 ? "#c9a96a" : "#8a6d43"}"/><path d="M${r(cx)} ${r(cy)} L${r(rr[0])} ${r(rr[1])} L${r(tip[0])} ${r(tip[1])} Z" fill="${i % 2 ? "#efe0b8" : "#d8bd85"}"/>`;
  }
  g += `<circle cx="${cx}" cy="${cy}" r="1" fill="#b23a2a"/>` + text(cx, cy - 13.2, "N", 3.6, "#6b4f2a", `font-weight="bold"`);
  S.hinten(g);
}

/* =====================================================================
   TEILE — 1: die Ozeane (unsichtbare Fläche, sichtbarer Name)
   ===================================================================== */
function ozean(polys, labels, worte, tipp) {
  let k = `<path d="${polys.map((p) => weg(linie(p, 5))).join("")}" fill="#fff" fill-opacity=".003"/>`;
  for (const [lo, la, zeilen, gr] of labels) { const [x, y] = P(lo, la); zeilen.forEach((z, i) => { k += halo(x, y + i * gr * 1.15, z, gr, "#2c6687", "#cfe6ee", `font-style="italic" font-weight="bold" letter-spacing=".5"`, 0.7); }); }
  S.teil(Object.assign({ x: 0, y: 0, kunst: k, tipp }, worte));
}
